Hier ist eine C++-Funktion, die auf einen std::string mit Markdown-formatiertem Text verweist und einen std::string mit HTML-formatiertem Text zurückgibt:

```cpp
#include <iostream>
#include <string>
#include <boost/algorithm/string.hpp>
#include <boost/algorithm/string/replace.hpp>
#include <boost/algorithm/string/split.hpp>

std::string convertToHtml(const std::string& markdown) {
    std::string html;

    // Replace Markdown newlines with HTML line breaks
    boost::replace_all(markdown, "\n", "<br />");

    // Convert Markdown headers to HTML headers
    boost::replace_all(markdown, "# ", "<h1>");
    boost::replace_all(markdown, "## ", "<h2>");
    boost::replace_all(markdown, "### ", "<h3>");
    boost::replace_all(markdown, "#### ", "<h4>");
    boost::replace_all(markdown, "##### ", "<h5>");
    boost::replace_all(markdown, "###### ", "<h6>");

    // Convert Markdown links to HTML links
    std::vector<std::string> linkParts;
    boost::split(linkParts, markdown, [](char c) { return c == ' '; });
    for (std::size_t I = 0; I < linkParts.size(); ++i) {
        if (linkParts[i].find("http") != std::string::npos) {
            std::string link = linkParts[i];
            std::string linkText;
            if (i + 1 < linkParts.size()) {
                linkText = linkParts[i + 1];
                ++i;
            }
            html += "<a href=\"" + link + "\">" + linkText + "</a>";
        }
    }

    // Convert Markdown bold text to HTML bold text
    boost::replace_all(markdown, "**", "<strong>");
    boost::replace_all(markdown, "**", "</strong>");

    // Convert Markdown italic text to HTML italic text
    boost::replace_all(markdown, "*", "<em>");
    boost::replace_all(markdown, "*", "</em>");

    // Convert Markdown block quotes to HTML block quotes
    boost::replace_all(markdown, "> ", "<blockquote>");
    boost::replace_all(markdown, "</p>", "</blockquote></p>");

    // Convert Markdown code blocks to HTML code blocks
    std::string codeBlockStart = "\n```";
    std::size_t codeBlockStartPos = markdown.find(codeBlockStart);
    while (codeBlockStartPos != std::string::npos) {
        std::string codeBlock = markdown.substr(codeBlockStartPos + 3);
        std::size_t codeBlockEndPos = codeBlock.find("\n```");
        html += "<pre><code>" + codeBlock.substr(0, codeBlockEndPos) + "</code></pre>";
        markdown.replace(codeBlockStartPos, codeBlockStart.size() + codeBlockEndPos + 3, "");
        codeBlockStartPos = markdown.find(codeBlockStart);
    }

    // Convert Markdown lists to HTML lists
    std::vector<std::string> items;
    boost::split(items, markdown, [](char c) { return c == '\n'; });
    std::string listHtml;
    bool isList = false;
    for (std::size_t I = 0; I < items.size(); ++i) {
        std::string item = items[i];
        if (boost::starts_with(item, "- ") || boost::starts_with(item, "* ")) {
            if (!isList) {
                isList = true;
                listHtml += "<ul>";
            }
            std::string listItem = item.substr(2);
            listHtml += "<li>" + listItem + "</li>";
        } else {
            if (isList) {
                isList = false;
                listHtml += "</ul>";
            }
            html += "<p>" + item + "</p>";
        }
    }

    // Combine all converted parts into one HTML string
    html = "<div>" + listHtml + html + "</div>";

    return html;
}

int main() {
    std::string markdown = "### Hello, world!\n\nThis is a [link](https://example.com) to an example website.\n\nHere's some **bold** and *italic* text.\n\n> This is a block quote.\n\n```\nThis is a code block.\n```\n\n- Item 1\n- Item 2\n  - Nested item";

    std::string html = convertToHtml(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

Die Funktion `convertToHtml` nimmt einen `std::string` mit Markdown-formatiertem Text als Eingabe und gibt einen `std::string` mit HTML-formatiertem Text zurück. Die Funktion verwaltet die Konvertierung von verschiedenen Markdown-Elementen, wie Überschriften, Links, Fett-, Kursiv-, Blockquote- und Code-Text, sowie Listen, und erstellt die korrespondierenden HTML-Elemente. Die Konvertierung von Markdown in HTML erfolgt durch die Anwendung von Boost-Algorithmen und String-Manipulationen. Die Beispielfunktion `main` demonstriert die Verwendung der Funktion und gibt das resultierende HTML an die Konsole aus.

