function isPrimeNumber(arr) {
  for (let I = 0; I < arr.length; i++) {
    if (isPrime(arr[i])) {
      console.log(`Die Primzahl ist ${arr[i]}`);
      return;
    }
  }
}

function isPrime(num) {
  if (num < 2) {
    return false;
  }
  for (let I = 2; I <= Math.sqrt(num); i++) {
    if (num % I === 0) {
      return false;
    }
  }
  return true;
}

// Beispielaufruf:
const myArray = [2, 7, 12, 23, 41];
isPrimeNumber(myArray);
```

