Hier ist ein C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes zählt:

```c++
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string wordToCount;
    int count = 0;

    // Eingabe des Suchworts
    cout << "Geben Sie das Suchwort ein: ";
    cin >> wordToCount;

    // Öffnen der Textdatei
    ifstream file("input.txt");

    if (!file.is_open()) {
        cerr << "Fehler: Datei konnte nicht geöffnet werden." << endl;
        return 1;
    }

    // Lesen der Datei Zeile für Zeile
    string line;
    while (getline(file, line)) {
        // Trennen der Zeile in Wörter
        size_t pos = 0;
        string token;
        while ((pos = line.find(" ")) != string::npos) {
            token = line.substr(pos, line.find(" ") - pos);
            line.erase(pos, line.find(" ") + 1);

            // Suchen des Suchworts im aktuellen Token
            if (token == wordToCount) {
                count++;
            }
        }

        // Letztes Token des aktuellen Zeilen
        if (line != "") {
            if (line == wordToCount) {
                count++;
            }
        }
    }

    // Schließen der Datei
    file.close();

    // Ausgabe des Ergebnisses
    cout << "Das Suchwort '" << wordToCount << "' trat " << count << " Mal auf." << endl;

    return 0;
}
```

Das Programm liest die Eingabe des Suchworts vom Benutzer ein und öffnet die Datei "input.txt". Es liest die Datei Zeile für Zeile ein und trennt jede Zeile in Wörter. Jedes Token wird auf das Suchwort überprüft und bei Treffer wird die Anzahl der Vorkommen erhöht. Nach dem Lesen der gesamten Datei wird das Ergebnis ausgegeben.

